function drawLocalOfflineQR(payloadStr) {
const canvas = document.getElementById("qr-canvas");
if (!canvas) return;
const ctx = canvas.getContext("2d");
ctx.fillStyle = "#FFFFFF";
ctx.fillRect(0, 0, 54, 54);
let h = 2166136261;
for (let i = 0; i < payloadStr.length; i++) {
h ^= payloadStr.charCodeAt(i);
h = Math.imul(h, 16777619);
}
ctx.fillStyle = "#0F172A";
const drawFinder = (ox, oy) => {
ctx.fillRect(ox, oy, 14, 14);
ctx.fillStyle = "#FFFFFF";
ctx.fillRect(ox + 2, oy + 2, 10, 10);
ctx.fillStyle = "#635BFF";
ctx.fillRect(ox + 4, oy + 4, 6, 6);
ctx.fillStyle = "#0F172A";
};
drawFinder(2, 2);
drawFinder(38, 2);
drawFinder(2, 38);
for (let r = 0; r < 11; r++) {
for (let c = 0; c < 11; c++) {
if ((r < 4 && c < 4) || (r < 4 && c > 6) || (r > 6 && c < 4)) continue;
const bit = ((h >>> ((r * 11 + c) % 28)) ^ (r * 17 + c * 31)) & 1;
if (bit) {
ctx.fillStyle = ((r + c) % 3 === 0) ? "#635BFF" : "#0F172A";
ctx.fillRect(4 + c * 4, 4 + r * 4, 3, 3);
}
}
}
}
